import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom fused kernel for Subtract+Mean+GELU+ResidualAdd
fused_kernel_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_op_kernel(
    const float* gemm_out, const float* sub_param,
    const float* orig_input, float* output,
    int batch_size, int out_features, int in_features
) {
    extern __shared__ float shared[];
    int batch = blockIdx.x;
    int tid = threadIdx.x;
    int threads = blockDim.x;

    // 1. Subtract parameter and compute mean
    const float* gemm_row = gemm_out + batch * out_features;
    float sum = 0.0f;

    // Subtract and partial sum
    for(int i = tid; i < out_features; i += threads) {
        sum += gemm_row[i] - sub_param[i];
    }

    shared[tid] = sum;
    __syncthreads();

    // Parallel reduction
    for(int stride = threads/2; stride > 0; stride >>= 1) {
        if(tid < stride) shared[tid] += shared[tid + stride];
        __syncthreads();
    }

    // 2. GELU activation
    float mean = shared[0] / out_features;
    float gelu = 0.5f * mean * (1.0f + erff(mean * 0.7071067811865475f));

    // 3. Residual add with broadcasting
    const float* orig_row = orig_input + batch * in_features;
    float* out_row = output + batch * in_features;

    for(int i = tid; i < in_features; i += threads) {
        out_row[i] = orig_row[i] + gelu;
    }
}

torch::Tensor fused_op_cuda(
    torch::Tensor gemm_out,
    torch::Tensor sub_param,
    torch::Tensor orig_input
) {
    auto output = torch::empty_like(orig_input);
    int batch_size = gemm_out.size(0);
    int threads = 512;

    fused_op_kernel<<<batch_size, threads, threads*sizeof(float)>>>(
        gemm_out.data_ptr<float>(),
        sub_param.data_ptr<float>(),
        orig_input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        gemm_out.size(1),
        orig_input.size(1)
    );

    return output;
}
"""

fused_kernel_cpp = "torch::Tensor fused_op_cuda(torch::Tensor, torch::Tensor, torch::Tensor);"
fused_op = load_inline(
    name='fused_op',
    cpp_sources=fused_kernel_cpp,
    cuda_sources=fused_kernel_code,
    functions=['fused_op_cuda'],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, bias=True):
        super().__init__()
        self.gemm = nn.Linear(in_features, out_features, bias=bias)
        self.subtract = nn.Parameter(torch.randn(out_features))
        self.fused_op = fused_op

    def forward(self, x):
        original_x = x.clone().detach()
        x = self.gemm(x)
        return self.fused_op.fused_op_cuda(x, self.subtract, original_x)
